xml.variables:
# Import necessary libraries import ccxt import pandas as pd
# Set API keys for Binance Derivatives api_key = 'your_api_key_here' api_secret = 'your_api_secret_here'
# Initialize CCXT exchange with API keys exchange = ccxt.binance({ 'apiKey': api_key, 'apiSecret': api_secret, })
def check_rise_market(symbol): # Fetch candlestick data (15-minute candles) ohlcv = exchange.fetch_ohlcv( symbol=symbol, timeframe='15m', since=None, limit=30 )
# Convert OHLCV into a pandas DataFrame for easier analysis df = pd.DataFrame(ohlcv, columns=['timestamp', 'open', 'high', 'low', 'close', 'volume'])
# Calculate the 20-period moving average (MA) df['ma'] = df['close'].rolling(window=20).mean()
# Check if the current price is above the MA and the previous day's close if len(df) > 1: return df.iloc[-1]['high'] >= df.iloc[-2]['close'] and df.iloc[-1]['high'] > df.iloc[-1]['ma'] else: return False
def check_position(symbol): # Fetch current position (long or short) positions = exchange.fetch_positions() for p in positions: if p['symbol'] == symbol and p['side'] == 'BUY': return True return False
def open_long_position(symbol, amount): # Open a long position with the specified amount exchange.create_order( symbol=symbol, type='LIMIT', side='BUY', amount=amount, price=float(exchange.fetch_ticker(symbol)['info']['markPrice']) )
def close_position(symbol): # Close all positions of the specified symbol for pos in exchange.fetch_positions(): if pos['symbol'] == symbol: exchange.create_order( symbol=symbol, type='STOP', side='SELL', amount=pos['size'], price=float(exchange.fetch_ticker(symbol)['info']['markPrice']) )
def main(): # Define the trading parameters symbol = 'BTCUSDT' amount = 0.1 # Amount to trade (in BTC) threshold = 0.001 # Threshold for checking market rise
while True: try: # Check if the market is rising if check_rise_market(symbol): if not check_position(symbol): # Only open a new position if there isn't one already open_long_position(symbol, amount) print(f'Opened long position on {symbol} with amount {amount}') else: print('Position already exists') else: if check_position(symbol): # If the market is not rising and we have an existing position, close it close_position(symbol) print(f'Closed long position on {symbol}')
except Exception as e: print(f'Error: {str(e)}')
if __name__ == '__main__': main()
